"""Restore public selected-task triage without touching a checkout or a service.
Usage: python3 public_replay.py path/to/public/src/owner/presentation.mjs NEW_DIR
Copy the two verified files under NEW_DIR into a clean worktree of the public
baseline to continue locally. Run node --test tests/dashboard-attention-triage.test.mjs.
The base presentation is from backup commit 09a2f56 (also unchanged at 0ac9e5a).
This backs up only the public, selected-task list. The separate private
cumulative workbench additionally filters cross-PA attention and restores focus.
"""
from pathlib import Path
import hashlib, sys
BASE = 'd3e64ee7f268456fc3380bc2c061a140d7d133e93f93e30418166b21770e1415'
TARGET = '165dab756dc4d45308856ed2d35fb206b8ab5c6e5c7ba0f53108a94492fe7a41'
TEST_HASH = '432a85f3d7cb5845ece2a7acf7b294ebf99d3f2aae5b517a29fa2da21c0ca7cd'
EDITS = [('<option value="attention">待处理</option>', '<option value="attention">待处理</option><option value="waiting_input">等待输入</option><option value="source_issue">阻塞或失败</option><option value="stale_snapshot">过期快照</option>'), ("  const attention = item => item.stale === true || ['needs_input','failed'].includes(item.source_status) || (Number.isSafeInteger(item.pending_action_count) && item.pending_action_count > 0);", "  const attention = item => (item.state==='available' && item.archived!==true && ['proposed','running','needs_input'].includes(item.source_status) && typeof item.blocker==='string' && item.blocker.trim().length>0) || item.stale === true || ['needs_input','failed'].includes(item.source_status) || (Number.isSafeInteger(item.pending_action_count) && item.pending_action_count > 0);"), ("  const matches = item => filter === 'attention' ? attention(item) : filter === 'running' ? item.state === 'available' && item.source_status === 'running' : filter === 'completed' ? item.state === 'available' && item.source_status === 'completed' : true;", "  // Category membership uses already-read data only. Old and archived questions\n  // remain available in the broad attention list, not in current-work queues.\n  const current = item => item.state === 'available' && item.archived !== true && item.stale !== true;\n  const triage = {\n    waiting_input: all.filter(item=>current(item) && (item.source_status==='needs_input' || (Number.isSafeInteger(item.pending_action_count) && item.pending_action_count>0))),\n    source_issue: all.filter(item=>current(item) && (item.source_status==='failed' || (['proposed','running','needs_input'].includes(item.source_status) && typeof item.blocker==='string' && item.blocker.trim().length>0))),\n    stale_snapshot: all.filter(item=>item.state==='available' && item.stale===true)\n  };\n  const category = Object.hasOwn(triage,filter) ? new Set(triage[filter]) : null;\n  const matches = item => category ? category.has(item) : filter === 'attention' ? attention(item) : filter === 'running' ? item.state === 'available' && item.source_status === 'running' : filter === 'completed' ? item.state === 'available' && item.source_status === 'completed' : true;"), ('    counts: {running:all.filter', '    triage,\n    counts: {running:all.filter')]
TEST = 'import test from \'node:test\';\nimport assert from \'node:assert/strict\';\nimport {selectedWorkbench,ownerDashboardHtml} from \'../src/owner/presentation.mjs\';\n\nconst row=(id,changes={})=>({task_id:id,source_id:\'zot-main\',project_id:\'p\',run_id:\'r\',branch_id:\'b\',state:\'available\',task_name:id,source_status:\'running\',...changes});\nconst ids=(rows,key,query=\'\')=>selectedWorkbench(rows,key,query).visible.map(item=>item.task_id);\ntest(\'reason filters select actionable current rows independently, without mutating the snapshot\',()=>{\n  const rows=[row(\'question\',{source_status:\'needs_input\'}),row(\'still-running\',{pending_action_count:2,blocker:\'Dataset missing\'}),row(\'failure\',{source_status:\'failed\'}),row(\'stale\',{stale:true,source_status:\'needs_input\',pending_action_count:3,blocker:\'old\'}),row(\'archived\',{archived:true,source_status:\'needs_input\',pending_action_count:2}),row(\'withheld\',{state:\'withheld\',pending_action_count:2,blocker:\'x\',stale:true}),row(\'empty\',{pending_action_count:-1,blocker:\'  \'}),row(\'complete\',{source_status:\'completed\',blocker:\'Old issue\'}),row(\'unavailable\',{state:\'unavailable\',source_status:\'failed\'})];\n  const before=JSON.stringify(rows);\n  assert.deepEqual(ids(rows,\'waiting_input\'),[\'question\',\'still-running\']);\n  assert.deepEqual(ids(rows,\'source_issue\'),[\'still-running\',\'failure\']);\n  assert.deepEqual(ids(rows,\'stale_snapshot\'),[\'stale\']);\n  assert.deepEqual(ids(rows,\'waiting_input\',\'ＱＵＥＳＴＩＯＮ\'),[\'question\']);\n  assert.equal(JSON.stringify(rows),before);\n});\ntest(\'selected-task list offers all three reason filters; empty filters stay empty\',()=>{\n  const html=ownerDashboardHtml(\'test\');const dropdown=html.match(/<select id="task-filter"[^>]*>([\\s\\S]*?)<\\/select>/)[1];\n  for(const key of [\'waiting_input\',\'source_issue\',\'stale_snapshot\']){assert.match(dropdown,new RegExp(\'value="\'+key+\'"\'));assert.deepEqual(ids([row(\'clear\')],key),[]);}\n  assert.deepEqual(ids([row(\'stop\',{blocker:\'waiting for file\'})],\'attention\'),[\'stop\']);\n});\n'

def digest(text): return hashlib.sha256(text.encode("utf-8")).hexdigest()
if len(sys.argv)!=3: raise SystemExit(__doc__)
source,dst=Path(sys.argv[1]),Path(sys.argv[2])
if dst.exists(): raise SystemExit("Choose a new output directory.")
text=source.read_text(encoding="utf-8")
if digest(text)!=BASE: raise SystemExit("The public baseline does not match.")
for before,after in EDITS:
    if text.count(before)!=1: raise SystemExit("Base text differs; no files written.")
    text=text.replace(before,after)
if digest(text)!=TARGET or digest(TEST)!=TEST_HASH: raise SystemExit("Output validation failed.")
dst.mkdir()
for name,data in [("src/owner/presentation.mjs",text),("tests/dashboard-attention-triage.test.mjs",TEST)]:
    work=dst/name;work.parent.mkdir(parents=True,exist_ok=True);work.write_text(data,encoding="utf-8")
print("Restored the public selected-task filters and tests to",dst)
